<?php
require_once __DIR__."/../../middleware/user.php";require_once __DIR__."/../../config/koneksi.php";
$u=(int)$_SESSION["id_user"];$stmt=mysqli_prepare($koneksi,"SELECT rp.*,b.judul_buku,b.penulis_buku,b.cover_buku FROM reading_progress rp JOIN tbl_buku b ON b.id_buku=rp.id_buku WHERE rp.id_user=? ORDER BY rp.terakhir_dibaca DESC");mysqli_stmt_bind_param($stmt,"i",$u);mysqli_stmt_execute($stmt);$items=mysqli_stmt_get_result($stmt);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Riwayat Bacaan</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="<?= BASE_URL ?>/css/app.css"></head><body class="user-page"><?php include __DIR__."/../partials/header.php"; ?><main class="container"><h1>Riwayat Bacaan</h1><div class="grid"><?php if(mysqli_num_rows($items)===0):?><p>Belum ada buku yang dibaca.</p><?php endif;?><?php while($x=mysqli_fetch_assoc($items)):$p=$x["total_halaman"]?min(100,round($x["halaman_terakhir"]/$x["total_halaman"]*100)):0;?><article class="book"><img src="<?= BASE_URL ?>/uploads/cover/<?= e($x["cover_buku"]) ?>" alt=""><h3><?= e($x["judul_buku"]) ?></h3><p><?= e($x["penulis_buku"]) ?></p><p>Halaman <?= (int)$x["halaman_terakhir"] ?>/<?= (int)$x["total_halaman"] ?> (<?= $p ?>%)</p><a href="<?= BASE_URL ?>/user/buku/read.php?id=<?= (int)$x["id_buku"] ?>">Lanjutkan membaca</a></article><?php endwhile;?></div></main></body></html>
